export function disciplineReference(name,value) {
 const ref=entries[name==='Ясновидение'?'Прорицание':name];if(!ref)return null;
 return {...ref,name,value,powers:ref.powers.slice(0,value).map(([title,text,roll,difficulty,cost,duration],i)=>({level:i+1,title,text,roll,difficulty,cost,duration,url:`${book}#:~:text=${encodeURIComponent(title)}`})),url:`${book}#:~:text=${encodeURIComponent(ref.bookName)}`};
}
